"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";
import type { TableSchema } from "@/components/moneytrees/data-table-v2/types";
import { SkeletonRows, TableEmptyState } from "@/components/moneytrees/data-table-v2/table-primitives";

type Props<T> = {
  /** Schema-driven column descriptors — shared with `<DataTableV2>`. */
  schema: TableSchema<T>;
  /** Latest rows, newest first. */
  rows: T[];
  getRowId: (row: T) => string;
  /** Per-row height in px. Defaults to 56 to align with the bubble pill spacing. */
  rowHeight?: number;
  /** Max visible height before the body scrolls. */
  maxHeight?: number;
  className?: string;
  emptyMessage?: string;
  /**
   * Render shimmer skeleton rows instead of the empty message. Pass `true`
   * while the first query is still resolving so an unresolved feed doesn't
   * read as "no data".
   */
  isLoading?: boolean;
  /** Number of skeleton rows to render while loading. */
  skeletonRows?: number;
  onRowClick?: (row: T) => void;
};

/**
 * Append-streaming live feed for the dashboard. Consumes the same
 * `TableSchema<T>` as `<DataTableV2>` so column primitives (source badge,
 * sentiment chip, ticker pills, etc.) are reused without duplication.
 *
 * Newly arriving rows animate in from the top via motion's `layout` +
 * `AnimatePresence`. Existing rows shift down with FLIP. The legacy
 * `.mt-new-row` keyframe pulse layers on top for the gold flash. Honours
 * `prefers-reduced-motion` — animations collapse to instant transitions.
 *
 * Virtualization is intentionally NOT used here. TanStack Virtual + motion
 * layout don't compose cleanly (Virtual's absolute positioning short-circuits
 * the FLIP measurement step). The dashboard caps the live feed at 100 rows,
 * which renders fine without windowing. If scale grows past ~500 we'll
 * revisit (likely with a Virtual + transform-only animation strategy).
 */
export function LiveFeedTable<T>({
  schema,
  rows,
  getRowId,
  rowHeight = 56,
  maxHeight = 600,
  className,
  emptyMessage = "Nothing yet.",
  isLoading = false,
  skeletonRows = 6,
  onRowClick,
}: Props<T>) {
  const reduced = useReducedMotion();
  const prevIds = React.useRef<Set<string>>(new Set());

  const newIds = React.useMemo(() => {
    const next = new Set<string>();
    rows.forEach((r) => {
      const id = getRowId(r);
      if (!prevIds.current.has(id)) next.add(id);
    });
    return next;
  }, [rows, getRowId]);

  React.useEffect(() => {
    prevIds.current = new Set(rows.map(getRowId));
  }, [rows, getRowId]);

  return (
    <div
      className={cn(
        // .mt-liquid-css already supplies the rim (border + bubble shadow);
        // only the bubble rounding is layered on top. A second Tailwind
        // `border` here would double the rim if the token width ever changes.
        "mt-liquid-css overflow-hidden rounded-bubble-lg",
        className,
      )}
      data-variant="card"
    >
      <div className="flex items-center border-b border-[var(--glass-edge)] px-4 py-2.5 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        {schema.map((col) => (
          <div
            key={col.id}
            className={cn(
              "flex-1 min-w-0",
              col.align === "right" && "text-right",
              col.align === "center" && "text-center",
            )}
            style={col.size ? { flex: `0 0 ${col.size}px` } : undefined}
          >
            {col.header}
          </div>
        ))}
      </div>
      <div className="relative overflow-y-auto" style={{ maxHeight }}>
        {isLoading ? (
          <SkeletonRows count={skeletonRows} rowHeight={rowHeight} />
        ) : rows.length === 0 ? (
          <TableEmptyState message={emptyMessage} />
        ) : (
          <AnimatePresence initial={false}>
            {rows.map((row) => {
              const id = getRowId(row);
              const isNew = newIds.has(id);
              const rowEl = (
                <motion.div
                  key={id}
                  layout={!reduced}
                  initial={reduced ? false : { opacity: 0, y: -rowHeight, scale: 0.98 }}
                  animate={reduced ? false : { opacity: 1, y: 0, scale: 1 }}
                  exit={reduced ? undefined : { opacity: 0, scale: 0.98 }}
                  transition={{ type: "spring", stiffness: 360, damping: 28, mass: 0.7 }}
                  onClick={onRowClick ? () => onRowClick(row) : undefined}
                  className={cn(
                    "flex items-center border-b border-[var(--glass-edge)]/60 px-4 text-sm",
                    "last:border-b-0",
                    onRowClick && "cursor-pointer hover:bg-[var(--glass-tint-card)]",
                    isNew && "mt-new-row",
                  )}
                  style={{ height: rowHeight }}
                >
                  {schema.map((col) => {
                    const accessor =
                      col.accessor ?? ((r: T) => (r as Record<string, unknown>)[col.id]);
                    const value = accessor(row);
                    return (
                      <div
                        key={col.id}
                        className={cn(
                          "flex-1 min-w-0 truncate",
                          col.align === "right" && "text-right",
                          col.align === "center" && "text-center",
                          col.className,
                        )}
                        style={col.size ? { flex: `0 0 ${col.size}px` } : undefined}
                      >
                        {col.render(value, row)}
                      </div>
                    );
                  })}
                </motion.div>
              );
              return rowEl;
            })}
          </AnimatePresence>
        )}
      </div>
    </div>
  );
}
